import{_ as a,o as r,c as o,a5 as e}from"./chunks/framework.BqnnR8ku.js";const u=JSON.parse('{"title":"存储管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/storage.md","filePath":"zh/guide/storage.md"}'),l={name:"zh/guide/storage.md"};function i(d,t,n,s,h,g){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="存储管理" tabindex="-1">存储管理 <a class="header-anchor" href="#存储管理" aria-label="Permalink to &quot;存储管理&quot;">​</a></h1><p>服务器模式下，项目的源文件、译文与导出产物都保存在<strong>对象存储</strong>里：默认使用服务器本地磁盘，也可以接入你自己的 S3 兼容对象存储。本页讲两件事：<strong>普通用户</strong>如何为项目选择与迁移存储、管理源文件版本；<strong>管理员</strong>如何配置站点存储、审核自有存储与设置存储政策。</p><div class="info custom-block"><p class="custom-block-title">适用范围</p><p>存储能力随服务器模式（含 Docker）提供。本地模式的数据直接落在本机数据目录，无需（也没有）存储配置界面；部署侧的 <code>server.storage.*</code> 配置见 <a href="/LinguaFlow/zh/guide/configuration.html#server-storage-—-对象存储">配置文件与环境变量</a>。</p></div><h2 id="两种存储方式" tabindex="-1">两种存储方式 <a class="header-anchor" href="#两种存储方式" aria-label="Permalink to &quot;两种存储方式&quot;">​</a></h2><p>新建项目时选定的存储空间决定文件保存在哪里：</p><table tabindex="0"><thead><tr><th>方式</th><th>文件在哪</th><th>适合</th></tr></thead><tbody><tr><td><strong>站点托管</strong></td><td>管理员在存储管理页配置的站点空间（本地磁盘目录或 S3）</td><td>默认方式，开箱即用</td></tr><tr><td><strong>自有存储</strong>（BYOS）</td><td>用户 / 组织自行接入的 S3 兼容存储连接</td><td>想把文件留在自己的 bucket 里</td></tr></tbody></table><p>站点采用哪种政策由管理员设定（见下文 <a href="#站点存储政策">站点存储政策</a>），可选仅站点托管、两者皆可或强制自有存储。</p><h2 id="新建项目-选择存储空间" tabindex="-1">新建项目：选择存储空间 <a class="header-anchor" href="#新建项目-选择存储空间" aria-label="Permalink to &quot;新建项目：选择存储空间&quot;">​</a></h2><p>服务器模式下创建项目时，界面会要求<strong>明确选择一个存储空间</strong>（不会自动替你选第一项）：</p><ul><li>无可用目标时会提示「服务尚未提供可用空间及默认选择，暂不能创建项目」，此时联系管理员配置存储</li><li>每个候选空间都会标注不可选原因（如「当前政策不接受此空间」「存储服务正在维护」「空间额度不足」）</li></ul><h2 id="项目存储-绑定与迁移" tabindex="-1">项目存储：绑定与迁移 <a class="header-anchor" href="#项目存储-绑定与迁移" aria-label="Permalink to &quot;项目存储：绑定与迁移&quot;">​</a></h2><p>项目工作区的 <strong>项目存储</strong> 页签展示当前绑定：</p><ul><li><strong>当前空间</strong> — 项目文件所在空间、存储代次与站点存储维护状态</li><li><strong>重新绑定</strong> — 空项目可直接换绑其他空间</li><li><strong>迁移已有数据</strong> — 非空项目支持把全部文件迁移到另一空间（复制 → 验证 → 切换 → 清理）；迁移期间限制新增持久内容，迁移过程遵循站点维护状态</li></ul><p>迁移是持久化的存储任务，可在 <a href="/LinguaFlow/zh/guide/projects.html#任务中心跨项目任务列表">任务中心</a> 追踪进度；失败可重试，已完成阶段不重跑。</p><h2 id="源文件与固定交付" tabindex="-1">源文件与固定交付 <a class="header-anchor" href="#源文件与固定交付" aria-label="Permalink to &quot;源文件与固定交付&quot;">​</a></h2><p>资源级抽屉「源文件与固定交付」提供版本化的源文件管理：</p><ul><li><strong>版本历史</strong> — 每个版本记录文件格式、解析器版本、原件大小与 SHA-256，可区分当前版本与历史版本</li><li><strong>更新源文件</strong> — 预览-确认式替换（见下节）</li><li><strong>同字节修复</strong> — 原件损坏或误改时，上传与原版本逐字节一致的文件修复历史版本；不切换工作区、不改动译文</li><li><strong>固定交付</strong> — 把当前译文保存为交付版本，之后源文件再怎么更新都不影响它；需要时可用「使用旧快照重建」回滚，也支持下载与删除</li></ul><h2 id="更新源文件" tabindex="-1">更新源文件 <a class="header-anchor" href="#更新源文件" aria-label="Permalink to &quot;更新源文件&quot;">​</a></h2><p>替换已有资源的源文件走<strong>预览-确认</strong>流程，不会静默覆盖：</p><ol><li>选择新源文件</li><li>点 <strong>预览变化</strong> — 查看新增段落、原文变更段落、删除段落与未变化段落的统计</li><li>逐个候选 <strong>确认更新</strong> — 每次更新生成可追踪的存储任务</li></ol><div class="tip custom-block"><p class="custom-block-title">旧版本没有可信基线时</p><p>若旧版本缺少可信的原件基线，界面会提供 <strong>下载旧成果 JSON 快照</strong>，先留底再更新。</p></div><h2 id="会话与草稿保护" tabindex="-1">会话与草稿保护 <a class="header-anchor" href="#会话与草稿保护" aria-label="Permalink to &quot;会话与草稿保护&quot;">​</a></h2><p>存储操作与翻译编辑共用一套保护：</p><ul><li>有<strong>未保存的译文或备注</strong>时发起源文件更新等操作，会弹出「有未保存的译文或备注」对话框，可选 <strong>保存并继续 / 放弃并继续 / 取消</strong></li><li>登录态或资源归属变化后，未完成的操作会被拦截；请求结果未知时提示「请求结果待确认」并引导查看原任务，避免重复提交</li></ul><h2 id="存储任务" tabindex="-1">存储任务 <a class="header-anchor" href="#存储任务" aria-label="Permalink to &quot;存储任务&quot;">​</a></h2><p>任务中心的任务类型除翻译、术语同步外，还包括<strong>文件存储</strong>任务（文件上传 / 源文件更新 / 同字节修复）。详情抽屉展示处理阶段（等待执行 → 候选已准备 → 复制文件 → 验证文件 → 切换存储绑定 → 清理旧文件 → 处理完成）与空间清理状态，并提供「前往项目存储」「恢复原任务」入口。</p><h2 id="管理员-存储管理页" tabindex="-1">管理员：存储管理页 <a class="header-anchor" href="#管理员-存储管理页" aria-label="Permalink to &quot;管理员：存储管理页&quot;">​</a></h2><p>管理员后台的 <strong>存储管理</strong> 页（<code>/admin/storage</code>）分三块：</p><h3 id="总览与诊断" tabindex="-1">总览与诊断 <a class="header-anchor" href="#总览与诊断" aria-label="Permalink to &quot;总览与诊断&quot;">​</a></h3><ul><li><strong>容量明细</strong> — 各空间的「登记占用 / 空间配额」</li><li><strong>只读诊断</strong> — 缺失对象、损坏对象数、恢复积压、最早未完成意图等健康指标</li></ul><h3 id="存储连接与空间" tabindex="-1">存储连接与空间 <a class="header-anchor" href="#存储连接与空间" aria-label="Permalink to &quot;存储连接与空间&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>新建连接 / 新建空间</td><td>连接指向一个 S3 兼容端点，空间是连接下带容量配额的 bucket 前缀</td></tr><tr><td>更新授权 / 撤销授权</td><td>管理连接的访问凭据；密钥只写不回显</td></tr><tr><td>只读检测 / 写入检测</td><td>验证连接可用性；写入检测会创建并清理探测对象</td></tr><tr><td>启用 / 禁用连接、设为只读 / 恢复可写</td><td>控制空间可用状态</td></tr></tbody></table><p>用户与组织也可在各自页面管理<strong>自有存储连接</strong>（个人 / 组织级），管理员可在此看到站点级连接。</p><h3 id="站点存储政策" tabindex="-1">站点存储政策 <a class="header-anchor" href="#站点存储政策" aria-label="Permalink to &quot;站点存储政策&quot;">​</a></h3><p>设定全站的存储方式：</p><table tabindex="0"><thead><tr><th>政策模式</th><th>含义</th></tr></thead><tbody><tr><td>仅站点托管</td><td>所有项目只能用站点空间</td></tr><tr><td>站点托管或自有存储</td><td>用户可为项目选择站点空间或自有存储</td></tr><tr><td>必须使用自有存储</td><td>项目必须绑定用户 / 组织自己的存储</td></tr></tbody></table><p>政策还包含<strong>默认选择</strong>与<strong>逻辑容量上限</strong>；修改政策时会与未保存的项目数据做冲突核对。政策生效由服务端逐操作准入（能力发现接口向下发放可用操作快照），被拒绝的操作会给出稳定原因（如存储维护中、连接已禁用、空间只读、未授权）。</p><h3 id="维护状态" tabindex="-1">维护状态 <a class="header-anchor" href="#维护状态" aria-label="Permalink to &quot;维护状态&quot;">​</a></h3><p>站点进入存储<strong>维护态</strong>时，所有存储写入被拒绝（任务中心会显示对应状态）。除管理员手动设置外，启动时检测到未完成的旧版数据迁移任务也会自动进入维护态，处理完再恢复。</p><h2 id="旧数据迁移与备份-独立工具" tabindex="-1">旧数据迁移与备份（独立工具） <a class="header-anchor" href="#旧数据迁移与备份-独立工具" aria-label="Permalink to &quot;旧数据迁移与备份（独立工具）&quot;">​</a></h2><p>从旧版本升级（把 <code>data/jobs</code> 下的文件搬入新存储）或做灾备时，使用独立命令行工具 <code>linguaflow-storage-migrate</code>：支持清点、演练、正式迁移、断点续跑、回滚，以及离线一致性备份与恢复校验。用法见 <a href="/LinguaFlow/zh/guide/cli.html#linguaflow-storage-migrate-命令">CLI 命令参考 · 存储迁移与备份工具</a>。</p><div class="warning custom-block"><p class="custom-block-title">迁移前先备份</p><p>正式迁移要求同时提供 <code>--offline</code> 与 <code>--backup-confirmed</code>——先完成备份并确认，再执行迁移。</p></div><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/LinguaFlow/zh/guide/configuration.html#server-storage-—-对象存储">配置文件与环境变量</a> — <code>server.storage.*</code> 部署配置</li><li><a href="/LinguaFlow/zh/guide/cli.html#linguaflow-storage-migrate-命令">CLI 命令参考</a> — 迁移与备份工具</li><li><a href="/LinguaFlow/zh/guide/projects.html">项目管理</a> — 项目工作区与源文件操作</li><li><a href="/LinguaFlow/zh/guide/admin.html">管理员后台</a> — 用户、系统设置与审计</li><li><a href="/LinguaFlow/zh/api/">API 参考</a> — 存储接口与错误码</li></ul>',44)])])}const p=a(l,[["render",i]]);export{u as __pageData,p as default};
